var ph = PhaseManager.get_current_phase_instance()
if ph.get("awaiting_ability_reroll"):
	ph.execute_action({"type": "DECLINE_ABILITY_REROLL", "actor_unit_id": "U_BEAST_SNAGGA_BOYZ_B", "player": 1})
if ph.get("awaiting_reroll_decision"):
	ph.execute_action({"type": "DECLINE_COMMAND_REROLL", "actor_unit_id": "U_BEAST_SNAGGA_BOYZ_B", "player": 1})
for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name) != "StratagemDialog":
		c.hide()
		c.queue_free()
var dist = int(ph.pending_charges["U_BEAST_SNAGGA_BOYZ_B"]["distance"])
print("[wp-o6] charge roll ", dist)
return dist >= 4

var ph = PhaseManager.get_current_phase_instance()
var dist = int(ph.pending_charges["U_BEAST_SNAGGA_BOYZ_B"]["distance"])
var mv = AIDecisionMaker._compute_charge_move(GameState.create_snapshot(), "U_BEAST_SNAGGA_BOYZ_B", dist, ["U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H"], 1)
if str(mv.get("type", "")) != "APPLY_CHARGE_MOVE":
	return "NO_MOVE"
mv["player"] = 1
var r = NetworkIntegration.route_action(mv)
return r.get("success", false)
